(199, '8944756258', 'Tata Sampann Chilli Powder with Natural Oils Lal Mirchi Powder - 100g', '', 'masal73543', 'powde76947', 75, 0, 'uploads/masal73543/undefined_masal73543_powde76947_8307049102_1722518150736.webp', '8307049102', 0, '<p>Description :&nbsp;Tata Sampann Chilli Powder Masala is made from the choicest chillies and gives your curries and gravies a quintessential thick-red texture and irresistible aroma.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;12 months</p><p>FSSAI License :&nbsp;FSSAI No 10013022002508</p><p>Ingredients :&nbsp;Chilli</p><p>Manufacturer Name :&nbsp;Tata Chemicals Limited</p><p>Manufacturer Address :&nbsp;Tata Chemicals Limited, Leela Business Park, Andheri-kurla Road, Andheri East, Mumbai, Maharashtra.</p>', 100, 0, 1, '2024-08-01 07:45:50', 'admin', '2024-08-01 07:45:50', 'admin', NULL),
(200, '8680011854', 'Everest Chhole Masala - 50g', '', 'masal73543', 'powde76947', 45, 0, 'uploads/masal73543/8680011854_masal73543_powde76947_816709581_1722518417536.webp', '816709581', 0, '<p>Description :&nbsp;Everest presents their authentic range of masalas that are blended with a wide variety of handpicked and selected spices that bring a whole new flavour and meaning to your dishes. Rake up your favourite recipes and cuisines by adding this magical blend of Everest masalas.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;12 months</p><p>Ingredients :&nbsp;Dried red chili peppers, Dried Garlic, Ginger powder, Sesame, Mustard seeds, Turmeric, Coriander, Bay leaves, Star anise and Fennel.</p><p>Manufacturer Name :&nbsp;Everest Food Products Pvt. Ltd</p><p>Manufacturer Address :&nbsp;Everest Food Products Pvt. Ltd, Krushal Towers, Commercial Soceity, 5Th Road, Brindavan Colony, Tilak Nagar, Chembur, Mumbai, Maharashtra 400089</p>', 100, 0, 1, '2024-08-01 07:50:17', 'admin', '2024-08-01 07:50:17', 'admin', NULL),
(201, '6294280176', 'Suhana Chicken Tandoori Paste - 100g', '', 'masal73543', 'powde76947', 55, 0, 'uploads/masal73543/undefined_masal73543_powde76947_5128495964_1722592737090.webp', '5128495964', 0, '<p>Description :&nbsp;Suhana Chicken Tandoori Paste: Suhana Chicken Tandoori Paste is a flavorful marinade for making tandoori chicken at home. It contains a blend of spices and herbs that add authentic flavor to the dish, including ginger, garlic, coriander, cumin, and red chili powder. Simply marinate chicken pieces in the paste and grill or roast for delicious</p><p>Shelf Life :&nbsp;12 months</p><p>Manufacturer Name :&nbsp;PRAVIN MASALEWALE</p><p>Manufacturer Address :&nbsp;PRAVIN MASALEWALE : - H-At. 44 Hadapsar Industrial Estate Pune.</p>', 100, 0, 1, '2024-08-02 04:28:58', 'admin', '2024-08-02 04:28:58', 'admin', NULL),
(202, '2128618948', 'India Gate Classic Hyderabadi Biryani Masala - 120g', '', 'masal73543', 'powde76947', 125, 0, 'uploads/masal73543/undefined_masal73543_powde76947_8648587310_1722593269629.webp', '8648587310', 0, '<p>Description :&nbsp;India Gate Classic Hyderabadi Biryani Masala is a special blend of spices meticulously crafted to recreate the authentic flavors of Hyderabadi biryani. This aromatic masala mix is made with premium quality spices like cardamom, cinnamon, cloves, and bay leaves, carefully selected and ground to perfection. India Gate Classic Hyderabadi Biryani Masala adds depth, richness, and complexity to your biryani dishes, making them truly irresistible. Elevate your cooking with the exquisite flavors of India Gate Classic Hyderabadi Biryani Masala.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;12 months</p><p>Manufacturer Name :&nbsp;Krbl Ltd</p>', 100, 0, 1, '2024-08-02 04:37:49', 'admin', '2024-08-02 04:37:49', 'admin', NULL),
(203, '5815766584', 'Catch Masala Amchur Powder - 100g', '', 'masal73543', 'powde76947', 95, 0, 'uploads/masal73543/5815766584_masal73543_powde76947_1660800771_1722595235406.webp', '1660800771', 0, '<p>Description :&nbsp;Catch Dry Mango Powder is made from the pulp of high-quality dry mangoes and can be added to cooked vegetable dishes, chicken, meat, and even to your fruits.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;12 months</p><p>FSSAI License :&nbsp;FSSAI No 10016011003518</p><p>Manufacturer Name :&nbsp;DS SPICECO PVT LTD</p>', 100, 0, 1, '2024-08-02 05:10:35', 'admin', '2024-08-02 05:10:35', 'admin', NULL),
(204, '1667690902', 'L.G Asafoetida Powder - 50g', '', 'masal73543', 'powde76947', 92, 0, 'uploads/masal73543/undefined_masal73543_powde76947_179349703_1722596724272.webp', '179349703', 0, '<p>Description :&nbsp;LG Powder - Asafoetida taste is bitter and acrid; however, when fried lightly, it adds amazing smell and taste. It makes the dishes easier to digest.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;15 months</p><p>Manufacturer Name :&nbsp;L.G</p>', 100, 0, 1, '2024-08-02 05:35:24', 'admin', '2024-08-02 05:35:24', 'admin', NULL),
(205, '4075143393', 'Everest Amchur Powder - 50g', '', 'masal73543', 'powde76947', 50, 0, 'uploads/masal73543/4075143393_masal73543_powde76947_816709581_1722597018439.webp', '816709581', 0, '<p>Description :&nbsp;Eastern Amchur (Dry Mango) Powder is known for its purity, freshness, hygiene, rich aroma and longer shelf life. It is a widely used powder that adds mouth-watering taste to your curries, food and chatts.</p><p>Country of Origin :&nbsp;India</p><p>Shelf Life :&nbsp;15 months</p><p>Manufacturer Name :&nbsp;Everest Food Products Pvt. Ltd</p><p>Manufacturer Address :&nbsp;Everest Food Products Pvt. Ltd, Krushal Towers, Commercial Soceity, 5Th Road, Brindavan Colony, Tilak Nagar, Chembur, Mumbai, Maharashtra 400089</p>', 100, 0, 1, '2024-08-02 05:40:18', 'admin', '2024-08-02 05:40:18', 'admin', NULL);
