(767, '2463592316', 'Dove Daily Shine Conditioner-175ml', '', 'bath,26350', 'hairo72850', 245, 0, 'uploads/bath,26350/undefined_bath,26350_hairo72850_3587678745_1723839301193.png', '3587678745', 0, '<ul><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Detangles\r\n Hair, Giving It An Unbelievable Shine:�Tangles and frizz, make hair \r\nlook dull and lead to increased hair breakage while combing. That\'s why \r\nshampoo alone is not enough. Use Dove Daily Shine Conditioner every time\r\n after shampoo for detangled, smooth hair with an unbelievable shine. \r\nInfused with Nutritive serum, it detangles hair along the lengths, \r\nadding shine, taming frizz, making hair smooth that your comb will slide\r\n through.�</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Country of Origin : India</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Shelf Life : 24 months</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Manufacturer Name : Hindustan Unilever Limited</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Manufacturer Address : Hindustan Unilever Limited, Unilever House, B.D.Sawant Marg, Chakala, Andheri (E), Mumbai - 400 099.</p></li></ul>', 100, 1, 1, '2024-08-16 14:45:01', 'admin', '2024-08-16 14:45:01', 'admin', NULL),
(768, '2119081967', 'L\'Oreal Dream Lengths Conditioner-180ml', '', 'bath,26350', 'hairo72850', 269, 0, 'uploads/bath,26350/undefined_bath,26350_hairo72850_782072936_1723839450847.png', '782072936', 0, '<ul><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Loreal\r\n Paris - Save the last 3 cms of your hair and get the long hair of your \r\ndreams with the new L\'Oreal Paris Dream Lengths Detangling Conditioner. A\r\n perfect conditioner for dry and damaged hair, the Dream Lengths \r\nDetangling Conditioner instantly detangles long hair for 5X smoother \r\nhair with 50% less breakage.</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Country of Origin : India</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Shelf Life : 35 months</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Manufacturer Name : Loreal India Pvt Ltd</p></li><li><p class=\"font-norms block typography_paragraph-small__Cqv9t   font-subtitle sm:mb-1.5 sm:!text-lg\">Manufacturer Address : Loreal India Pvt Ltd, A-Wing, 8th Floor, Marathon Futurex, N.M. Joshi Marg, Lower Parel (E) Mumbai 400013.</p></li></ul>', 100, 1, 1, '2024-08-16 14:47:30', 'admin', '2024-08-16 14:47:30', 'admin', NULL),
